mapper.select:
SELECT r.ROOM_ID AS roomId, r.PRODUCT_ID AS productId, r.SELLER_ID AS sellerId, r.BUYER_ID AS buyerId, r.CREATED_AT AS createdAt, r.LAST_MESSAGE_AT AS lastMessageAt, r.LAST_MESSAGE AS lastMessage, r.TRADE_STATUS AS tradeStatus,
p.TITLE AS productTitle, p.PRICE AS price, p.STATUS AS status,
(SELECT IMAGE_PATH FROM PRODUCT_IMAGES WHERE PRODUCT_ID = r.PRODUCT_ID AND ORDERS = 1 ) AS productImageUrl FROM CHAT_ROOM r JOIN PRODUCT p ON r.PRODUCT_ID = p.PRODUCT_ID WHERE r.ROOM_ID = #{roomId}

SELECT r.ROOM_ID AS roomId, r.PRODUCT_ID AS productId, r.SELLER_ID AS sellerId, r.BUYER_ID AS buyerId, r.CREATED_AT AS createdAt, r.LAST_MESSAGE_AT AS lastMessageAt, r.LAST_MESSAGE AS lastMessage, r.TRADE_STATUS AS tradeStatus,
p.TITLE AS productTitle, p.PRICE AS price, p.STATUS AS status,
(SELECT IMAGE_PATH FROM PRODUCT_IMAGES WHERE PRODUCT_ID = r.PRODUCT_ID AND ORDERS = 1 ) AS productImageUrl FROM CHAT_ROOM r JOIN PRODUCT p ON r.PRODUCT_ID = p.PRODUCT_ID WHERE r.PRODUCT_ID = #{productId} AND r.SELLER_ID = #{sellerId} AND r.BUYER_ID = #{buyerId}

SELECT COUNT(*)
FROM CHAT_MESSAGE
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{userId}
  AND IS_READ = 'N'

mapper.update:
UPDATE CHAT_MESSAGE
SET IS_READ = 'Y',
    READ_AT = SYSDATE
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{userId}
  AND IS_READ = 'N'

UPDATE CHAT_ROOM
SET LAST_MESSAGE    = #{lastMessage},
    LAST_MESSAGE_AT = (
        SELECT SENT_AT
        FROM CHAT_MESSAGE
        WHERE MESSAGE_ID = #{messageId}
    )
WHERE ROOM_ID = #{roomId}

UPDATE CHAT_ROOM
SET TRADE_STATUS = #{tradeStatus}
WHERE ROOM_ID    = #{roomId}
